/**
 * Bundles src/worker-entry.ts into a single classic-mode script and embeds
 * it as the string exported by src/worker-source.ts.
 *
 *   node scripts/build-worker.mjs          # regenerate
 *   node scripts/build-worker.mjs --check  # exit 1 if the committed file is stale
 *
 * Runs before `npm run build`. The generated file is committed so that
 * `npm test` and editors see a real module without a build step.
 */

import { rollup } from 'rollup';
import typescript from '@rollup/plugin-typescript';
import terser from '@rollup/plugin-terser';
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const entry = join(root, 'src', 'worker-entry.ts');
const target = join(root, 'src', 'worker-source.ts');

export async function buildWorkerSource() {
  const bundle = await rollup({
    input: entry,
    plugins: [
      typescript({
        tsconfig: join(root, 'tsconfig.json'),
        declaration: false,
        declarationMap: false,
        sourceMap: false,
        exclude: ['**/*.test.ts', '**/*.spec.ts'],
      }),
      terser({ compress: { drop_console: false } }),
    ],
  });
  const { output } = await bundle.generate({ format: 'iife' });
  await bundle.close();
  return output[0].code;
}

export function renderModule(code) {
  return [
    '/**',
    ' * GENERATED by scripts/build-worker.mjs from src/worker-entry.ts — do not edit.',
    ' *',
    ' * The worker script, embedded as a string so the library is self-contained',
    ' * and needs no static file deployment by default. Classic mode (no',
    ' * `type: "module"`) because Firefox has been unreliable with module workers',
    ' * loaded from Blob URLs.',
    ' */',
    `const workerSource = ${JSON.stringify(code)};`,
    '',
    'export default workerSource;',
    '',
  ].join('\n');
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];

if (isMain) {
  const check = process.argv.includes('--check');
  const rendered = renderModule(await buildWorkerSource());
  if (check) {
    let current = '';
    try {
      current = readFileSync(target, 'utf8');
    } catch {
      // Missing counts as stale.
    }
    // Git may check the file out with CRLF; only the content matters.
    const normalise = (text) => text.replace(/\r\n/g, '\n');
    if (normalise(current) !== normalise(rendered)) {
      console.error('src/worker-source.ts is stale — run `npm run build:worker`.');
      process.exit(1);
    }
    console.log('src/worker-source.ts is up to date.');
  } else {
    writeFileSync(target, rendered);
    console.log(`wrote ${target} (${rendered.length} bytes)`);
  }
}
